def can_blend_all_colors(s):
    for i in range(len(s)):
        if s[i] == '.':
            left = s[i-1] if i > 0 else '.'
            right = s[i+1] if i < len(s) - 1 else '.'
            if left in 'ABC' and right in 'ABC':
